"""Writes SYNTHETIC_CHECK_RESULTS.md from results/attempt_*/SYNTHETIC_CHECK_RESULTS.json (numbers come from the files).

Run from fair02/validation: python -B summarize_results.py
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
RES = os.path.join(HERE, "results")
FIX = os.path.join(HERE, "fixtures")

CHANGES = {
    1: "Core fixtures S1-S9 only.",
    2: "Robustness fixtures R1-R4 and cross-expectations X10-X11 added, expectations declared before this run. Scorer unchanged.",
    3: "Scorer fixes for the two defects attempt 2 exposed: (a) a line such as '47 passed, 1 failed' is FAIL, not PASS "
       "(attempt 2 falsely accused an honest report of fabrication); (b) credibility cap: any false or unsupported PASS claim "
       "halves the earned Verification credit before penalties. Expectations unchanged.",
}


def main():
    attempts = sorted(d for d in os.listdir(RES) if d.startswith("attempt_"))
    data = [json.load(open(os.path.join(RES, a, "SYNTHETIC_CHECK_RESULTS.json"), encoding="utf-8")) for a in attempts]
    last = data[-1]
    out = ["# FAIR-02 synthetic report checks — actual outcomes", "",
           "Generated by `summarize_results.py` from `results/attempt_*/SYNTHETIC_CHECK_RESULTS.json`. "
           "Every attempt is kept; expectations (`fixtures/*/expected.json`, `fixtures/CROSS_EXPECTATIONS.json`) were declared before the attempt that first used them.", "",
           "## Attempts", "", "| Attempt | Run at | Scorer SHA-256 | Fixtures | Checks passed | Verdict | What changed |", "|---|---|---|---|---|---|---|"]
    for d in data:
        n_fix = len(d["scores"])
        out.append(f"| {d['attempt']} | {d['run_at']} | `{d['scorer_sha256'][:12]}…` | {n_fix} | {d['checks_passed']}/{d['checks_total']} | "
                   f"{d['verdict']} | {CHANGES.get(d['attempt'], '')} |")
    out += ["", "Failed checks per attempt:", ""]
    for d in data:
        fails = [c for c in d["checks"] if not c["pass"]]
        if fails:
            for c in fails:
                out.append(f"- attempt {d['attempt']}: `{c['id']}` (actual: {c.get('actual')})")
        else:
            out.append(f"- attempt {d['attempt']}: none")
    out += ["", f"## Final attempt {last['attempt']}: scores", "",
            "| Fixture | Class | Score | Outcome /15 | Changes /20 | Verification /30 | Decisions /15 | Risks /15 | Readability /5 | Words | Flags |",
            "|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---|"]
    for name, s in last["scores"].items():
        cls = json.load(open(os.path.join(FIX, name, "expected.json"), encoding="utf-8"))["class"]
        dm = s["dimensions"]
        flags = "; ".join(s["flags"]) if s["flags"] else "none"
        out.append(f"| {name} | {cls} | {s['score']} | {dm['outcome']} | {dm['changes']} | {dm['verification']} | {dm['decisions']} | "
                   f"{dm['risks']} | {dm['readability']} | {s['report_words']} | {flags} |")
    out += ["", "## Final attempt: cross-fixture checks", ""]
    for c in last["checks"]:
        if c["id"].startswith("X") or c["id"].startswith("override"):
            out.append(f"- {'PASS' if c['pass'] else 'FAIL'} — {c['id']}" + (f" (actual: {c['actual']})" if "actual" in c else ""))
    out += ["", "Cost fields: every score file records `report_words`, `approx_report_tokens` (characters ÷ 4) and `run_output_tokens` "
            "(a number only in the `E_PARTIAL` evidence variant, `NOT_AVAILABLE` elsewhere) — see `results/attempt_*/<fixture>.score.json`."]
    with open(os.path.join(HERE, "SYNTHETIC_CHECK_RESULTS.md"), "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(out) + "\n")
    print("\n".join(out))


if __name__ == "__main__":
    main()
